INSERT INTO `blogcontents` (`blogTitle`, `blogDate`, `blogText`, `blogImage`) VALUES
('Tote Bag Painting Workshop at Block 69 Café', '2024-05-15', 'We hosted an amazing tote bag painting workshop here at Block 69 Café! Singles and couples alike came together to express their creativity while enjoying our handcrafted coffee and non-coffee beverages. Guests painted their own unique tote bags, indulged in brunch, and had an unforgettable time in our cozy café space. Watch out for our next workshop — we would love to see you here!', 'blog_db_images/1_workshop.png'),
('Game On: Board Games at Block 69 Café', '2024-05-20', 'Looking for a fun way to spend your afternoon? Block 69 Café has you covered! We offer unlimited use of board games with any purchase, making us the perfect hangout spot for barkadas and families. Whether you are into strategy games or classic card games, we have something for everyone. Grab your favorite beverage — from our bestselling Spanish Latte to our refreshing Pink Paradise — and let the games begin!', 'blog_db_images/2_boardgames.jpg'),
('What''s New at Block 69 Café', '2024-06-01', 'Exciting things are happening at Block 69 Café! We have been expanding our menu with new matcha variants, refreshing fruit beverages, and hearty meal options to fuel your day. We are also proud to have been awarded a Recommendation badge by Restaurant Guru, one of the world''s most popular foodie websites with over 30 million monthly users. Thank you to all our customers for the continued love and support. Stay tuned for more updates, promos, and events coming your way!', 'blog_db_images/3_newfeatures.png');
